import json
from pathlib import Path

counts = {"INFO": 0, "WARN": 0, "ERROR": 0}
for line in Path("app.log").read_text().splitlines():
    for level in counts:
        if line.startswith(level + " "):
            counts[level] += 1
            break

Path("report.json").write_text(json.dumps(counts))
print(counts)

